//   $LAST_RUN_FILE  what became of the items you emitted before (read-only):
//                   {"items": [{"key": ..., "status": ..., "session_id": ...}]}
//   $OUTPUT_FILE    your decision — must be written before exit
const read = (name) => JSON.parse(fs.readFileSync(process.env[name], "utf8"));
const event = read("EVENT_FILE");
const state = read("STATE_FILE");
const lastRun = read("LAST_RUN_FILE");

// Only these actually started sessions — items over the per-run cap are
// deferred, so never mark work done just because you emitted it.
const inFlightOrDone = new Set(
  lastRun.items
    .filter((i) => i.status === "succeeded" || i.status === "running")
    .map((i) => i.key)
);

// Write exactly one of:
//   {"run": true}                     proceed to sessions
//   {"run": false, "reason": "..."}   skip this run
//   {"items": [{...}, {...}]}         one session per item
// Items are capped at 10 per run (max 50); extras run next time.
// An item's "id" is a unit of work, not an entity: "INC-1" runs once, ever.
// Add "version" (e.g. the upstream updated_at) so a reopened item counts as
// new work. An item whose session fails is released and can run again.
fs.writeFileSync(process.env.OUTPUT_FILE, JSON.stringify({ run: true }));
